const source = $('Has Recipient Email').item.json;
const raw = $json.output ?? $json.text ?? $json.response ?? $json.message?.content ?? '';
let parsed = null;
const rawStr = typeof raw === 'string' ? raw : JSON.stringify(raw);

try {
  const cleanedJsonStr = rawStr.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  parsed = JSON.parse(cleanedJsonStr);
} catch (e) {
  const match = rawStr.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (e2) {
      const subjMatch = rawStr.match(/"subject"\s*:\s*"([^"\\]*(?:\\.[^"\\]*)*)"/i);
      const bodyMatch = rawStr.match(/"(?:body|message)"\s*:\s*"([^"\\]*(?:\\.[^"\\]*)*)"/i);
      if (subjMatch && bodyMatch) {
        parsed = {
          subject: subjMatch[1].replace(/\\n/g, '\n').replace(/\\"/g, '"'),
          body: bodyMatch[1].replace(/\\n/g, '\n').replace(/\\"/g, '"')
        };
      }
    }
  }
}

const recipientName = (source.Name || '').trim();
const firstName = recipientName.split(/\s+/)[0] || 'there';
const company = (source.Company || '').trim();
const compFirstWord = company.split(/\s+/)[0].toLowerCase();

let subject = parsed && typeof parsed.subject === 'string' ? parsed.subject.trim() : '';
let body = parsed && typeof (parsed.body || parsed.message) === 'string' ? (parsed.body || parsed.message).trim() : '';

if (!body) {
  body = rawStr.replace(/^[^{]*\{/, '{').trim();
}

subject = subject.replace(/^[\"']|[\"']$/g, '').replace(/\[[^\]]*\]/g, '').replace(/[-–—\s]+$/, '').trim();
if (!subject || /^opportunities at/i.test(subject) || /^job application/i.test(subject) || /^application/i.test(subject) || subject.length < 5) {
  subject = company ? `Accelerating AI initiatives at ${company} — Tusha` : 'Accelerating Applied AI initiatives — Tusha';
} else if (company && compFirstWord && !subject.toLowerCase().includes(compFirstWord)) {
  subject = `${subject} — ${company}`;
}

let cleanBody = body.replace(/^[\"']|[\"']$/g, '').trim();
cleanBody = cleanBody.replace(/^```(?:json|markdown|text)?\s*/i, '').replace(/\s*```$/, '').trim();

const greetingRegex = /^(?:Dear|Hi|Hello|Hey)\s+[^,\n]+[,:]/i;
const nameOnlyGreetingRegex = new RegExp(`^${firstName}[,:]`, 'i');

if (greetingRegex.test(cleanBody)) {
  cleanBody = cleanBody.replace(greetingRegex, `Hi ${firstName},`);
} else if (nameOnlyGreetingRegex.test(cleanBody)) {
  cleanBody = cleanBody.replace(nameOnlyGreetingRegex, `Hi ${firstName},`);
} else {
  cleanBody = `Hi ${firstName},\n\n` + cleanBody;
}

cleanBody = cleanBody.replace(/(Hi\s+[^,\n]+,\s*\n+)(?:My name('s| is)[^,\n]+,?\s*\n*)/i, '$1');
cleanBody = cleanBody.replace(/(Hi\s+[^,\n]+,\s*\n+)(?:Hope you('re| are) having a [^.!?\n]+[.!?]\s*|Wow,?\s*[^.!?\n]+[.!?]\s*)/i, '$1');

cleanBody = cleanBody.replace(/\[[^\]]*\]/gi, '');
cleanBody = cleanBody.replace(/(?:To that effect,?\s*)?(?:I've included my resume|You can find my links|find them on the links below|links below|check out my links)[^.\n]*[.\n]?/gi, '');
cleanBody = cleanBody.replace(/The following is my signature:?/gi, '');
cleanBody = cleanBody.replace(/(?:\n|^)\s*(?:Sincerely|Best regards|Best|Warm regards|Regards|Thanks|Cheers),?\s*\n*.*$/is, '');
cleanBody = cleanBody.replace(/[\s\d\p{Extended_Pictographic}\u200d\uFE0F\uFE0E]+$/gu, '').trim();
cleanBody = cleanBody.replace(/[”\"']+$/, '').trim();
cleanBody = cleanBody.replace(/Tusha\s+Rahul\s+Bellamkond[oa]/gi, 'Tusha Rahul Bellamkonda');

cleanBody = cleanBody.split('\n').map(l => l.trim()).filter(Boolean).join('\n\n');

const RESUME_URL = 'https://drive.google.com/file/d/1LdWTaK1wir3d-tAdkDc52F7LEc7cELtl/view?usp=sharing';
const PORTFOLIO_URL = 'https://tusharahul.netlify.app';
const LINKEDIN_URL = 'https://linkedin.com/in/tusha-rahul';
const GITHUB_URL = 'https://github.com/Rahul6158';
const PHONE_NUMBER = '+91 6304747097';
const FULL_NAME = 'Tusha Rahul Bellamkonda';

const linksAndSignature = [
  'My portfolio & profiles for review:',
  `• Portfolio: ${PORTFOLIO_URL}`,
  `• LinkedIn: ${LINKEDIN_URL}`,
  `• Resume: ${RESUME_URL}`,
  `• GitHub: ${GITHUB_URL}`,
  '',
  'Best regards,',
  FULL_NAME,
  'Applied AI Engineer',
  PHONE_NUMBER
].join('\n');

const finalBody = cleanBody + '\n\n' + linksAndSignature;

return [{
  json: {
    ...source,
    emailSubject: subject,
    emailBody: finalBody
  }
}];
